import{_ as t,o as r,c as i,a3 as o}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"1.6 Control Structures for Different Materials (Further Reading)","description":"","frontmatter":{"translationSource":{"title":"1.6 不同种物料控制结构（拓展阅读）","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=36dBqcBcCjyVD88enH50kC","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/control-structures-for-different-materials"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/control-structures-for-different-materials"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/control-structures-for-different-materials"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/control-structures-for-different-materials"}]]},"headers":[],"relativePath":"control-structures-for-different-materials.md","filePath":"logistics/src/page-36dBqcBcCjyVD88enH50kC.md"}'),a={name:"control-structures-for-different-materials.md"};function n(s,e,l,p,h,c){return r(),i("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="_1-6-control-structures-for-different-materials-further-reading" tabindex="-1">1.6 Control Structures for Different Materials (Further Reading) <a class="header-anchor" href="#_1-6-control-structures-for-different-materials-further-reading" aria-label="Permalink to &quot;1.6 Control Structures for Different Materials (Further Reading)&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-23. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>36dBqcBcCjyVD88enH50kC</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=36dBqcBcCjyVD88enH50kC" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>See <a href="/endfield-skydoc/logistics-principles-and-frontier-research">Logistics Principles and Terminology</a>.</p><p><span id="source-block-TYzFDvSHTuUTc3BHvqUUUH"></span></p><h2 id="blocking-control-with-mixed-belts-and-pipes" tabindex="-1">Blocking Control with Mixed Belts and Pipes <a class="header-anchor" href="#blocking-control-with-mixed-belts-and-pipes" aria-label="Permalink to &quot;Blocking Control with Mixed Belts and Pipes&quot;">​</a></h2><p>For now, see Discord user radio&#39;s tutorial series <a href="https://beta.enka.network/endfield/aic/?id=V1x4c2j5p4P9W1" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=V1x4c2j5p4P9W1</a>.</p><details><summary>radio&#39;s tutorial series</summary><p>part 2 is sprinkler switches <a href="https://beta.enka.network/endfield/aic/?id=B4d8c6K5T2r4z5" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=B4d8c6K5T2r4z5</a></p><p>part 3 is zero-waste transmuters <a href="https://beta.enka.network/endfield/aic/?id=P7T0p6n0D2f6p6" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=P7T0p6n0D2f6p6</a></p><p>part 4 is compound stuffs <a href="https://beta.enka.network/endfield/aic/?id=M5B0F5J9s8C0t5" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=M5B0F5J9s8C0t5</a></p></details><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a07e9d2ecedd83cf.q90-0c951c6e3f5c6628.webp" alt="1.6 Control Structures for Different Materials (Further Reading)"></p><p>The original illustration is explained below from left to right.</p><p><strong>① Synchronized passage on two lines</strong></p><p>This structure is also called a lock, filter, latch, or switch. A converger combines two lines, then a splitter separates them again. Item filters determine which output each item type takes. In normal operation the two item types alternate. Each gets half the opportunities to pass, synchronizing the two lines. If either line is blocked, the other stops too. You can see this happen when the Stash in the diagram fills. Most logistics control devices build on this structure.</p><p><strong>② Priority merging</strong></p><p>Connect one line to the priority gate&#39;s converger directly through a splitter. Its priority depends on whether the splitter or the other input lines were placed first. Inputs without splitters have equal priority. The splitter line goes first if its splitter was placed before the other inputs, and yields if it was placed later. In the diagram the splitter was placed last, so the other line has priority.</p><p>When both lines have items ready, the gate always admits the higher-priority line first. The lower-priority line can enter only when there is a gap. If the higher-priority belt or pipe stays full, nothing gets through on the lower-priority line.</p><p><strong>③ Lower-priority lines fill gaps</strong></p><p>When supply on the high-priority line is intermittent, the lower-priority line fills the gaps. Gaps form naturally if upstream output is slower than the belt or pipe capacity. You can also create gaps by interrupting or limiting flow.</p><p><strong>④ Output priority on a facility with multiple outputs</strong></p><p>The previous examples use a splitter to influence which input a converger takes first. Here a facility has several outputs, and a converger affects which one it uses first. Connect a converger directly to an output port. Whether that route gains or loses priority depends on its weight relative to the other routes.</p><p>To find the weight, follow the route from the output port to the nearest downstream facility. Count each logistics component and each continuous belt or pipe as one segment, regardless of its length. In the diagram the route with the converger has weight 2, while the other route has weight 1. The converger route therefore has lower priority. The facility has only one full input line, and the higher-priority output can take the entire supply. All material goes there, leaving the lower-priority output idle.</p><p><strong>⑤ Materials take the lower-priority route when the higher-priority output is blocked</strong></p><p>If the higher-priority output backs up intermittently, materials are diverted to the lower-priority route during the blockage. The diagram adds a logistics component to the lower-priority line, raising its weight to 3. The higher-priority route still goes first even if its own weight rises to 2.</p><p>If a route with a priority converger and another route have the same weight, connection order determines output priority. The first route connected goes first.</p><p><span id="source-block-XBevRAqYsJ9tUuAGpz0Jqi"></span></p><h2 id="unpowered-reactor-crucible" tabindex="-1">Unpowered Reactor Crucible <a class="header-anchor" href="#unpowered-reactor-crucible" aria-label="Permalink to &quot;Unpowered Reactor Crucible&quot;">​</a></h2><p>See <a href="/endfield-skydoc/1-5-automatic-maximum-gross-production">1.5 Intelligent Maximum Gross Output</a> and <a href="/endfield-skydoc/some-simpler-adaptive-setups">Simpler Zero-Waste Devices</a>.</p><p>A Reactor Crucible has 5 slots for solids or liquids. Fill 4 with miscellaneous materials, then route the solid or liquid you want to control through the crucible, either in a loop or straight through, depending on the design. Route the solid or liquid you want to monitor through it too. If the monitored material becomes completely blocked, the material being controlled cannot enter the crucible.</p><p>This is mainly used <strong>to control a liquid with a solid or a solid with a liquid</strong>. For materials in the same phase, use a mixed pipe or belt.</p><p>Leaving the crucible powered also works, at the cost of power. Turning the crucible off through its controls prevents this setup from working.</p><p><span id="source-block-F8E9BNZJZ9KMebEI51DQLA"></span></p><h2 id="flow-duplication" tabindex="-1">Flow Duplication <a class="header-anchor" href="#flow-duplication" aria-label="Permalink to &quot;Flow Duplication&quot;">​</a></h2><p>See the filling and dismantling setup in <a href="/endfield-skydoc/some-simpler-adaptive-setups">Simpler Zero-Waste Devices</a>. Taking the complement twice lets the sensing branch set the output flow to exactly the same rate.</p></div>',1)])])}const f=t(a,[["render",n]]);export{u as __pageData,f as default};
